#!/usr/bin/env node
'use strict';
const fs = require('fs');

function main() {
  const path = process.argv[2];
  if (!path) {
    console.error('Usage: node extract.js <binary>');
    process.exit(1);
  }
  const buf = fs.readFileSync(path);

  if (buf.length < 64 || buf.readUInt32LE(0) !== 0x464c457f) {
    throw new Error('Not an ELF file');
  }

  // e_type (2 bytes at 16), e_phoff (8 @32), e_phentsize (2 @54), e_phnum (2 @56)
  const eType = buf.readUInt16LE(16);
  const ePhoff = buf.readBigUInt64LE(32);
  const ePhentsize = buf.readUInt16LE(54);
  const ePhnum = buf.readUInt16LE(56);

  const PT_LOAD = 1;
  const segments = [];
  for (let i = 0; i < ePhnum; i++) {
    const off = Number(ePhoff) + i * ePhentsize;
    if (off + 56 > buf.length) break;
    const p_type = buf.readUInt32LE(off + 0);
    const p_flags = buf.readUInt32LE(off + 4);
    const p_offset = Number(buf.readBigUInt64LE(off + 8));
    const p_vaddr = Number(buf.readBigUInt64LE(off + 16));
    const p_paddr = Number(buf.readBigUInt64LE(off + 24));
    const p_filesz = Number(buf.readBigUInt64LE(off + 32));
    const p_memsz = Number(buf.readBigUInt64LE(off + 40));
    const p_align = Number(buf.readBigUInt64LE(off + 48));
    if (p_type === PT_LOAD) {
      segments.push({ p_offset, p_vaddr, p_filesz, p_memsz, p_flags });
    }
  }

  const result = {};
  for (const seg of segments) {
    const end = seg.p_offset + seg.p_filesz;
    for (let o = seg.p_offset; o + 4 <= end; o += 4) {
      const addr = seg.p_vaddr + (o - seg.p_offset);
      const val = buf.readUInt32LE(o);
      result[String(addr)] = val;
    }
  }

  process.stdout.write(JSON.stringify(result) + '\n');
}

main();
